import * as React from "react";
import { Link } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import { trackEvent } from "../utils/analytics";
import {
  mapLiveProjectsWithImages,
  serviceRelatedProjectKeys,
  type LivePortfolioProject,
} from "../utils/livePortfolio";

type RelatedProjectsSectionProps = {
  serviceKey: keyof typeof serviceRelatedProjectKeys;
};

export default function RelatedProjectsSection({
  serviceKey,
}: RelatedProjectsSectionProps) {
  const { t } = useTranslation();
  const { language } = useI18next();

  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{
    key: string;
    href: string;
  }>) || [];
  const selectedProjectsPath = language === "fr" ? "/fr/selected-projects/" : "/en/selected-projects/";
  const liveProjects = (t("portfolio.live.items", { returnObjects: true }) as LivePortfolioProject[]) || [];
  const relatedProjectKeys = serviceRelatedProjectKeys[serviceKey] as readonly string[];
  const relatedProjects = mapLiveProjectsWithImages(
    liveProjects.filter((project) => relatedProjectKeys.includes(project.imageKey))
  );

  if (!relatedProjects.length) {
    return null;
  }

  return (
    <section className="mt-14 space-y-5">
      <div>
        <h2 className="text-2xl font-semibold text-accent">
          {t("services.relatedWork.title")}
        </h2>
        <p className="mt-2 max-w-3xl text-neutral-600">
          {t("services.relatedWork.subtitle")}
        </p>
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        {relatedProjects.map((project) => (
          <article
            key={`${serviceKey}-${project.imageKey}`}
            className="flex h-full flex-col overflow-hidden rounded-2xl border border-neutral-200 bg-secondary shadow-sm"
          >
            <div className="overflow-hidden border-b border-neutral-200 bg-primary/40">
              <img
                src={project.images.large.src}
                alt={project.images.large.alt || project.title}
                className="h-52 w-full object-cover"
                loading="lazy"
              />
            </div>

            <div className="flex flex-1 flex-col p-5">
              <div className="flex items-center gap-3">
                <img
                  src={project.images.logo.src}
                  alt={project.images.logo.alt || `${project.title} logo`}
                  className="h-10 w-auto"
                  loading="lazy"
                />
                <h3 className="text-lg font-semibold text-accent">{project.title}</h3>
              </div>

              <p className="mt-3 text-sm text-neutral">
                <span className="font-medium text-accent">{project.role}</span>
                {" · "}
                <span>{project.stack}</span>
              </p>

              {project.note ? <p className="mt-3 text-sm text-neutral">{project.note}</p> : null}

              <ul className="mt-4 space-y-2 text-sm text-accent">
                {project.highlights.slice(0, 3).map((highlight) => (
                  <li key={highlight} className="flex gap-2">
                    <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                    <span className="min-w-0">{highlight}</span>
                  </li>
                ))}
              </ul>

              <div className="mt-5 flex flex-wrap gap-2">
                {servicesItems
                  .filter((item) => item.key === serviceKey)
                  .map((item) => (
                    <span
                      key={`${project.title}-${item.key}`}
                      className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-1 text-xs font-medium text-accent"
                    >
                      {t(`services.${serviceKey}.h1`)}
                    </span>
                  ))}
              </div>

              <div className="mt-auto flex flex-wrap gap-3 pt-5">
                <Link
                  to={`${selectedProjectsPath}#${project.imageKey}`}
                  onClick={() =>
                    trackEvent("case_summary_click", {
                      source: `services.${serviceKey}.related`,
                      project_name: project.title,
                    })}
                  className="inline-flex items-center rounded-xl border border-neutral/25 bg-primary px-4 py-2 text-sm font-medium text-accent hover:bg-primary/70"
                >
                  {t("services.relatedWork.viewCase")}
                </Link>
                <a
                  href={project.href}
                  target="_blank"
                  rel="noreferrer"
                  onClick={() =>
                    trackEvent("portfolio_click", {
                      source: `services.${serviceKey}.related`,
                      project_name: project.title,
                      target_url: project.href,
                    })}
                  className="inline-flex items-center rounded-xl bg-accent px-4 py-2 text-sm font-semibold text-primary hover:opacity-90"
                >
                  {t("services.relatedWork.visitSite")}
                </a>
              </div>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}
